  const years=[...new Set([...dues.map(periodYear),...allMovements.map(value=>value.slice(0,4))])].sort().reverse();
  const sources={dues,donations:finance.donations,financings:finance.financings,expenses:finance.expenses};
  const datesByView={dues:item=>periodYear(item),donations:item=>item.donatedAt?.slice(0,4)||'',financings:item=>item.receivedAt?.slice(0,4)||'',expenses:item=>item.paidAt?.slice(0,4)||''};
